{
  "summary": "7 governed metrics: 6 certified, 1 uncertified (active_listings; their results are labelled exploratory).",
  "metrics": [
    {
      "name": "active_listings",
      "summary": "Number of distinct listings that were active on at least one day in the period.",
      "unit": "count",
      "version": "0.1.0",
      "certified": false
    },
    {
      "name": "commission_revenue",
      "summary": "Commission charged to dealers on paid orders, minus commission refunded to dealers when orders are refunded, in EUR.",
      "unit": "EUR",
      "version": "1.0.0",
      "certified": true
    },
    {
      "name": "gross_merchandise_value",
      "summary": "Value of paid orders before refunds, in EUR.",
      "unit": "EUR",
      "version": "1.0.0",
      "certified": true
    },
    {
      "name": "net_merchandise_value",
      "summary": "Value of paid orders minus refunds, in EUR.",
      "unit": "EUR",
      "version": "1.0.0",
      "certified": true
    },
    {
      "name": "paid_orders",
      "summary": "Number of paid orders, counted on the order date.",
      "unit": "count",
      "version": "1.0.0",
      "certified": true
    },
    {
      "name": "refund_rate",
      "summary": "Refunded value as a share of gross merchandise value, for paid orders.",
      "unit": "ratio",
      "version": "1.0.0",
      "certified": true
    },
    {
      "name": "take_rate",
      "summary": "Commission charged to dealers as a share of gross merchandise value, for paid orders, before any commission is refunded.",
      "unit": "ratio",
      "version": "1.0.0",
      "certified": true
    }
  ],
  "glossary": {
    "commission": [
      "commission_revenue",
      "take_rate"
    ],
    "listings": [
      "active_listings"
    ],
    "revenue": [
      "gross_merchandise_value",
      "net_merchandise_value",
      "commission_revenue"
    ],
    "sales": [
      "gross_merchandise_value",
      "paid_orders"
    ]
  },
  "next_step": "No glossary entry for 'days to sell'. Pick the metric whose definition fits the question; call describe_metric for details."
}
